sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var dateTime = new GlideDateTime();//MSSRBXSN-1818:After-Insert BR to set Expected Processing date and template_identification as 'EMPTY BASKET ID' in Parent Email record with empty Basket ID field value, modifications for MSSRBXSN-2705
    if (current.basket_id == "") {
        current.template_identification = 'EMPTY BASKET ID';
		current.expected_processing_date = new GlideDateTime();//current system time
    }
    if (current.stock_connect_trade == 'Yes' && current.basket_id != "") { //if Stock connect trade = Yes on Parent Email record for non-empty Basket ID
        dateTime.addSeconds(600); //add10minutes
        current.expected_processing_date = dateTime.getDisplayValue();
    }
	if (current.stock_connect_trade == 'No' && current.basket_id != "") { //if Stock connect trade = No on Parent Email record for non-empty Basket ID
        dateTime.addSeconds(900); //add15minutes
        current.expected_processing_date = dateTime.getDisplayValue();
    }
    current.setWorkflow(false);
    current.update();
    current.setWorkflow(true);

})(current, previous);
